#include <iostream>
using std::cout;
using std::endl;

int main()
{
    int   iHP = 100;
    int   iAttack = 7;
    float fMultiplier = 1.5f;

    float fCritical = iAttack * fMultiplier;

    int iFinal = static_cast<int>(fCritical);

    iHP = iHP - iFinal;

    char cGrade = 'A';

    cout << "크리티컬 데미지 : " << fCritical << endl;
    cout << "적용 데미지 : " << iFinal << endl;
    cout << "남은 HP : " << iHP << endl;
    cout << "등급 코드 : " << (int)cGrade << endl;

    return 0;
}
